import{_ as e,o as i,c as o,ah as l}from"./chunks/framework.CxfsPN6f.js";const a="/projects/Tankbot/en/latest/assets/image1.CHJ32TEZ.png",s="/projects/Tankbot/en/latest/assets/image2.BIIR0LWO.png",n="/projects/Tankbot/en/latest/assets/image3.BglfC96v.png",A="/projects/Tankbot/en/latest/assets/image4.CElE1puX.png",r="/projects/Tankbot/en/latest/assets/image5.BEOrXcP4.png",m="/projects/Tankbot/en/latest/assets/image6.DDesYjfO.png",h="data:image/png;base64,",g="/projects/Tankbot/en/latest/assets/image2.DL2hMWTu.jpeg",c="data:image/png;base64,",p="/projects/Tankbot/en/latest/assets/image4.iaRd3WFb.jpeg",d="/projects/Tankbot/en/latest/assets/image5.BJnYGX_m.jpeg",w="/projects/Tankbot/en/latest/assets/image6.SlbN7TEe.jpeg",k="data:image/png;base64,",x="/projects/Tankbot/en/latest/assets/image2.DoGx1HnJ.png",b="/projects/Tankbot/en/latest/assets/image3.DBeKcYw1.png",u="data:image/png;base64,",f="/projects/Tankbot/en/latest/assets/image5.CzhHXkv8.jpeg",y="/projects/Tankbot/en/latest/assets/image6.CoEseCTn.png",D="/projects/Tankbot/en/latest/assets/image7.CRnjr68p.jpeg",P="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAABoAAAAaCAYAAACpSkzOAAAACXBIWXMAAA7EAAAOxAGVKw4bAAAAB3RJTUUH5AUECS4yyoKIMAAAAG9JREFUSIlj/PDhw38GOgAmelgyPC1iQebs3buXagY7OzvjtoiBgYHBxMSEYkvOnDmDITb84mjUolGLRqxFD+YxBMlXMuwnlk+2RVQEGGUdClBIYlj3kAQ+HjBI4oiKACPosBXx1ACMo42TUYtgAAChIR/l4u9qCAAAAABJRU5ErkJggg==",N="/projects/Tankbot/en/latest/assets/image9.BjoVrYhd.jpeg",v="data:image/png;base64,",I="/projects/Tankbot/en/latest/assets/image11.Bq3vQE8B.jpeg",C="/projects/Tankbot/en/latest/assets/image12.BviImVUn.jpeg",E="data:image/png;base64,",U="/projects/Tankbot/en/latest/assets/image14.B2k0cmwv.png",z="data:image/png;base64,",T=JSON.parse('{"title":"3.Set Development Environment","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Set Development Environment.md","filePath":"docs/3. Set Development Environment.md"}'),F={name:"docs/3. Set Development Environment.md"};function K(j,t,L,V,Y,Q){return i(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="_3-set-development-environment" tabindex="-1">3.Set Development Environment <a class="header-anchor" href="#_3-set-development-environment" aria-label="Permalink to &quot;3.Set Development Environment&quot;">​</a></h1><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p>To avoid compilation failure and influence on normal use, please activate Keil software after installation.</p></div><p>For activation method, you can refer to the file “Keil Activation Tutorial” ”saved in “Keil Installation Package and mcuisp Dowdloader”. If you use Keil for commercial purpose, please purchase legitimate version.</p><h2 id="_3-1-keil-software-installation" tabindex="-1">3.1 Keil software installation <a class="header-anchor" href="#_3-1-keil-software-installation" aria-label="Permalink to &quot;3.1 Keil software installation&quot;">​</a></h2><p>Keil C51 is a powerful software customized for microcontroller.</p><ol><li><p>Please double click to open “mdk500.exe” file in “Keil Installation Package and mcuisp Dowdloader” folder.</p></li><li><p>Tick “I agree”.</p></li></ol><img loading="lazy" height="373" width="553" class="common_img" src="'+a+'" style="width:800px;"><ol start="3"><li>Select the folder where Keil will be installed.</li></ol><img loading="lazy" height="373" width="553" class="common_img" src="'+s+'" style="width:800px;"><ol start="4"><li>You will be required to enter the user information, and you can fill in at will.</li></ol><img loading="lazy" height="373" width="553" class="common_img" src="'+n+'" style="width:800px;"><ol start="5"><li>After entering, click “Next” to install.</li></ol><img loading="lazy" height="373" width="553" class="common_img" src="'+A+'" style="width:800px;"><ol start="6"><li>Please wait for a while, a window will pop up asking you to install this software, and just click “Install”</li></ol><img loading="lazy" height="232" width="449" class="common_img" src="'+r+'" style="width:800px;"><ol start="7"><li>Click “Finish” after installation.</li></ol><img loading="lazy" height="373" width="553" class="common_img" src="'+m+'" style="width:800px;"><h2 id="_3-2-keil-program-compilation" tabindex="-1">3.2 Keil program compilation <a class="header-anchor" href="#_3-2-keil-program-compilation" aria-label="Permalink to &quot;3.2 Keil program compilation&quot;">​</a></h2><p><img loading="lazy" height="44" width="44" class="inline-icon" src="'+h+'" style="width:30px;">To facilitate user to quickly experience the games, all the programs have been compiled with the corresponding .hex file, therefore just have a look.</p><ol><li>Double click to open this project in this path “Sample Program-&gt;LED Flashing Program-&gt;STM32_LED”.</li></ol><img loading="lazy" height="392" width="419" class="common_img" src="'+g+'" style="width:800px;"><ol start="2"><li>After opening the project, you need to configure and set the file option. Click <img loading="lazy" height="25" width="23" class="inline-icon" src="'+c+'" style="width:30px;">, and then follow the below picture for the settings.</li></ol><img loading="lazy" height="735" width="1056" class="common_img" src="'+p+'" style="width:800px;"><ol start="3"><li>Next, compile the target file in this project, and click the three icons in red frame in sequence. After a while, the compilation result will be displayed in the bottom area. And the below picture shows that the compilation is successful.</li></ol><img loading="lazy" height="646" width="1011" class="common_img" src="'+d+'" style="width:800px;"><ol start="4"><li>As long as there is no error in compilation, .hex file will be automatically generated, which is saved in Obj folder.</li></ol><img loading="lazy" height="151" width="646" class="common_img" src="'+w+'" style="width:800px;"><h2 id="_3-3-methods-to-download-program" tabindex="-1">3.3 Methods to download program <a class="header-anchor" href="#_3-3-methods-to-download-program" aria-label="Permalink to &quot;3.3 Methods to download program&quot;">​</a></h2><p><img loading="lazy" height="44" width="44" class="inline-icon" src="'+k+'" style="width:30px;">Before downloading the program, please ensure the serial port driver is installed. The “ch341ser.exe” driver file can be found in “Keil Installation Package and mcuisp Downloader”</p><p>You can watch “Download Program” demo video in “Sample Program” folder.</p><ol><li><p>Connect USB downloader to controller through Dupont Line. Ensure GND to GND, RXD to TX, and TXD to Rx when connecting.</p></li><li><p><img loading="lazy" height="594" width="1091" class="common_img" src="'+x+'" style="width:800px;">Remove the Jumper cap, framed in red, on STM32 to make STM32 enter burning mode.</p></li></ol><img loading="lazy" height="594" width="603" class="common_img" src="'+b+'" style="width:800px;"><ol start="3"><li>Insert the downloader to any interface of the computer, and then switch on the controller. And you need to know the corresponding interface. Right click “Computer” and select “Attribute and Device Manager” in turns.</li></ol><p><img loading="lazy" height="44" width="44" class="inline-icon" src="'+u+'" style="width:30px;">If you remove the Jumper cap after switching on the controller, you need to press RST key to enter burning mode.</p><img loading="lazy" height="556" width="776" class="common_img" src="'+f+'" style="width:800px;"><ol start="4"><li><p>Mcuisp downloader will also be used. Please open <img loading="lazy" height="56" width="79" class="inline-icon" src="'+y+'" style="width:30px;"> saved in “Keil Installation Package and mcuisp Downloader” folder.</p></li><li><p>Select the corresponding serial port and baud rate. Here take COM11 for example. The interfaces may vary from each computer and please select the corresponding interface. COM1 generally is system communication port not actual port of the controller. The baud rate is 115200, and please don’t modify it.</p></li></ol><img loading="lazy" height="586" width="648" class="common_img" src="'+D+'" style="width:800px;"><ol start="6"><li>Click <img loading="lazy" height="26" width="26" class="inline-icon" src="'+P+'" style="width:30px;"> in the interface and select the folder where .hex file will be stored.</li></ol><img loading="lazy" height="534" width="946" class="common_img" src="'+N+'" style="width:800px;"><ol start="7"><li>Next, set the “<strong>STMISP</strong>”, and uncheck “ Execute after Programming” and other options remain the same.</li></ol><p><img loading="lazy" height="44" width="44" class="inline-icon" src="'+v+'" style="width:30px;">“Execute after Programming”: the program will be ran as soon as the program is burned into the microcontroller successfully. Hence it is not recommended to check this option. If you have checked this option, you need to keep away from the robotic arm’s moving area to avoid injury.</p><img loading="lazy" height="585" width="648" class="common_img" src="'+I+'" style="width:800px;"><ol start="8"><li>After setting, click “Start Programming” button, then the program can be burned into the controller. When the message “Anything OK” appears, it means that the program is burned completely.</li></ol><img loading="lazy" height="585" width="648" class="common_img" src="'+C+'" style="width:800px;"><p><img loading="lazy" height="44" width="44" class="inline-icon" src="'+E+'" style="width:30px;">If it prompts &quot;chip times out and does not response&quot;, it means that it has not switched to burning mode. First check whether the jumper cap is unplugged, and then press the RST button.</p><ol start="9"><li>Next, we can disconnect the USB downloader, and then reinsert the jumper cap into the STM32. Press the RST button to switch to the running mode. At this time, we can observe that the blue signal on the controller will continue to flash.</li></ol><img loading="lazy" height="1533" width="1533" class="common_img" src="'+U+'" style="width:800px;"><p><img loading="lazy" height="44" width="44" class="inline-icon" src="'+z+'" style="width:30px;">You can refer to this lesson to download the program in “4. Intelligent Games Lesson” and “5. Remote Control”.</p>',48)])])}const R=e(F,[["render",K]]);export{T as __pageData,R as default};
